void garantir_espaco(struct Produtos **arr, int *tam) {
    if (*tam >= 1000) {
        *tam *= 2;
        struct Produtos **nova = (struct Produtos **)realloc(*arr,
                   sizeof(struct Produtos *) * *tam);
